import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        email TEXT,
        role TEXT DEFAULT 'user',
        api_key_hash TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        actor TEXT,
        target TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    api_key = request.headers.get('X-API-Key', '')
    if not api_key or len(api_key) < 32:
        return jsonify({'error': 'Valid API key required'}), 401

    # Verify API key exists in database
    db = get_db()
    key_hash = hashlib.sha256(api_key.encode()).hexdigest()
    caller = db.execute('SELECT username, role FROM users WHERE api_key_hash = ?', (key_hash,)).fetchone()
    if not caller:
        return jsonify({'error': 'Invalid API key'}), 403

    field = request.args.get('field', 'username')
    query = request.args.get('q', '')

    # Restrict searchable fields to prevent information disclosure
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': f'Field must be one of: {allowed_fields}'}), 400

    if not query:
        return jsonify({'error': 'Query parameter q is required'}), 400

    # Build search query with field validation above
    sql = f"SELECT id, username, email, role FROM users WHERE {field} LIKE '%{query}%'"

    try:
        results = db.execute(sql).fetchall()
        users = [dict(row) for row in results]

        # Log the search action
        db.execute('INSERT INTO audit_log (action, actor, target) VALUES (?, ?, ?)',
                   ('user_search', caller['username'], f'{field}:{query}'))
        db.commit()

        return jsonify({'results': users, 'count': len(users)})
    except sqlite3.Error as e:
        return jsonify({'error': 'Search failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user details by ID."""
    api_key = request.headers.get('X-API-Key', '')
    if not api_key or len(api_key) < 32:
        return jsonify({'error': 'Valid API key required'}), 401

    db = get_db()
    key_hash = hashlib.sha256(api_key.encode()).hexdigest()
    caller = db.execute('SELECT username, role FROM users WHERE api_key_hash = ?', (key_hash,)).fetchone()
    if not caller:
        return jsonify({'error': 'Invalid API key'}), 403

    user = db.execute('SELECT id, username, email, role FROM users WHERE id = ?', (user_id,)).fetchone()
    if not user:
        return jsonify({'error': 'User not found'}), 404
    return jsonify(dict(user))

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
